import {forceConflicts,forceCategories,forceReviewDate,comparableFact,formatForceValue,evidenceFor} from './observatorio-force-data.mjs';
export function initForces({esc,search}){
 const root=document.getElementById('fuerzas');let conflict='ukraine',kind='inventory';
 function render(){const c=forceConflicts[conflict];
 root.innerHTML=`<div class="heading"><div><span class="eyebrow">HERRAMIENTAS / CONFLICTOS</span><h1>Balance de fuerzas</h1><p>Equipamiento y recursos, con evidencia visible.</p></div><span class="badge">Revisión de fuentes: ${forceReviewDate}</span></div>
 <div class="force-controls"><label>Conflicto<select id="force-conflict">${Object.entries(forceConflicts).map(([id,c])=>`<option value="${id}" ${id===conflict?'selected':''}>${esc(c.name)}</option>`).join('')}</select></label><div role="group" aria-label="Tipo de estadísticas"><button data-force-kind="inventory" aria-pressed="${kind==='inventory'}">Equipos e inventario</button><button data-force-kind="losses" aria-pressed="${kind==='losses'}">Pérdidas documentadas</button></div><button id="force-news">Noticias del conflicto ↗</button></div>
 <div class="force-versus"><div><small>BANDO A</small><h2>${esc(c.sides[0])}</h2></div><strong aria-label="Comparado con">VS</strong><div><small>BANDO B</small><h2>${esc(c.sides[1])}</h2></div></div>
 <p class="force-scope">${esc(c.scope)}</p><p class="muted">${esc(c.notes)}</p>
 ${kind==='losses'&&!c.facts.some(f=>f.kind===kind)?'<p class="panel">Todavía no hay recuentos de pérdidas verificados para este conflicto en el catálogo. Consulta Equipos e inventario para ver las fuentes disponibles.</p>':''}<div class="force-grid">${forceCategories.filter(([id])=>c.facts.some(f=>f.category===id&&f.kind===kind)||(kind==='inventory'&&['armor','drones','aircraft'].includes(id))).map(([id,label])=>{const f=c.facts.find(f=>f.category===id&&f.kind===kind);return `<article class="force-card ${f?'':'force-missing'}"><h3>${esc(f?.label||(id==='aircraft'&&kind==='inventory'?'Aviones':label))}</h3>${f?`<p class="force-period">${esc(f.period)}</p>`:''}<div class="force-values">${c.sides.map((side,i)=>`<div><small>${esc(side)}</small><strong>${esc(formatForceValue(f?.values[i],f?.qualifiers?.[i],f?.unit))}</strong></div>`).join('')}</div>${kind==='inventory'&&(c.equipment||[]).some(e=>e.category===id)?`<div class="force-equipment">${c.sides.map((side,i)=>`<section><h4>${esc(side)}</h4>${evidenceFor(conflict,id,i).map(e=>`<div class="force-evidence"><strong>${esc(e.title)}</strong><span class="force-status">${esc(e.status)}</span><small>${esc(e.period)}</small><p>${esc(e.detail)}</p><a href="${esc(e.source.url)}" target="_blank" rel="noopener noreferrer">${esc(e.source.name)} ↗</a></div>`).join('')||(!f||f.values[i]===null?'<p class="muted">No se encontró un inventario reciente verificable para este bando. No significa cero equipos.</p>':'<p class="muted">Cifra y alcance en la ficha.</p>')}</section>`).join('')}</div>`:''}${f&&comparableFact(f)&&f.values.some(v=>v>0)?`<div class="force-bars" aria-hidden="true"><span style="width:${100*f.values[0]/(f.values[0]+f.values[1])}%"></span><span style="flex:1"></span></div>`:''}${f?`<p>${esc(f.scope)}</p><details><summary>Fuente y alcance</summary><p>${esc(f.note)}</p><a target="_blank" rel="noopener noreferrer" href="${esc(f.source.url)}">${esc(f.source.name)} ↗</a></details>`:`<p class="muted">${kind==='losses'?'Sin recuento de pérdidas verificado en este catálogo.':'Sin inventario comparable verificado en este catálogo.'}</p>`}</article>`;}).join('')}</div>
 <details class="panel force-method"><summary>Categorías sin cifra verificada</summary><p>${forceCategories.filter(([id])=>!c.facts.some(f=>f.category===id&&f.kind===kind)).map(([,label])=>esc(label)).join(' · ')||'Todas las categorías tienen una ficha.'}</p><p>Sin un recuento comparable disponible en este catálogo. No se interpreta como cero.</p></details>
 <section class="panel force-method"><h2>Cómo leer el comparador</h2><p>Las fechas de cada tarjeta corresponden al periodo de los datos. La fecha de revisión no los convierte en cifras actuales. «Sin cifra verificada» no significa cero ni ausencia de esa capacidad.</p><p>Inventario, producción, entregas y despliegue son medidas distintas. Las pérdidas visualmente documentadas son un mínimo y pueden incluir material destruido, dañado, abandonado o capturado según la metodología de la fuente. No se descuentan automáticamente del inventario.</p><p>No se calcula un ganador: logística, entrenamiento, mantenimiento, terreno y apoyo externo también influyen. Este catálogo es una selección revisada, no un registro en tiempo real. Drones pequeños, de ataque y de reconocimiento no se agregan cuando sus definiciones no coinciden.</p></section>`;
 root.querySelector('#force-conflict').onchange=e=>{conflict=e.target.value;render();};root.querySelectorAll('[data-force-kind]').forEach(b=>b.onclick=()=>{kind=b.dataset.forceKind;render();});root.querySelector('#force-news').onclick=()=>search(c.name);
 }render();
}
